def create_connected_fill(grid, rows, cols):
    """Make cells that are 0 or have 0 neighbors into 0"""
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    changed = True
    while changed:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if output[r][c] == 0:
                    continue
                # Check all 8 neighbors
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr = r + dr
                        nc = c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == 0:  # Original position, not the evolving one
                                output[r][c] = 0
                                changed = True
                                break
                    if output[r][c] == 0:
                        break
    return output

